const roster=["PRISM","SCOPE","LENS","PARALLAX","FOCUS","SPECTRA","SIGNAL","SHADOW","FIELD","TICKTAG"];const $=x=>document.getElementById(x),K="mirror-v010";let s=JSON.parse(localStorage.getItem(K)||"null")||{project:"MIRROR Review",tracking:"MIRROR",state:"ACTIVE",selected:[],step:"INTAKE",done:0,total:7};function save(){localStorage.setItem(K,JSON.stringify(s))}function status(){let p=s.total?Math.round(s.done/s.total*100)+"%":"INDETERMINATE";$("status").textContent=`Project: ${s.project}\nTracking project: ${s.tracking}\nActive: ◈ MIRROR${s.selected.length?" > "+s.selected.join(", "):""}\nStage/step: REVIEW / ${s.step}\nOverall: ${p} (${s.done}/${s.total})\nState: ${s.state}\nQA: ${s.step==="FINAL"?"VERIFIED":"NOT RUN"}\nNext: ${s.done<7?"Continue pipeline":"Complete"}`;save()}roster.forEach(x=>{let d=document.createElement("article");d.className="card";d.innerHTML=`<h3>${x}</h3><button>Assign subordinate</button> <button>Independent</button>`;d.querySelectorAll("button").forEach((b,i)=>b.onclick=()=>{if(!s.selected.includes(x))s.selected.push(x);s.step=i?"INDEPENDENT HELPER":"DELEGATION";status()});$("helpers").appendChild(d)});["project","tracking","state"].forEach(k=>{$(k).value=s[k];$(k).oninput=e=>{s[k]=e.target.value;status()}});$("start").onclick=()=>{s.step="CLASSIFY";s.done=Math.max(1,s.done);$("output").textContent="Pipeline initialized. Select only required helpers. This build manages canonical routing/state and does not fabricate AI review results.";status()};$("export").onclick=()=>{let a=document.createElement("a"),b=new Blob([JSON.stringify(s,null,2)],{type:"application/json"});a.href=URL.createObjectURL(b);a.download="MIRROR_LCAS_state.json";a.click()};if("serviceWorker"in navigator)navigator.serviceWorker.register("sw.js");status();